#[path = "solution.rs"]
mod solution;

use solution::{LensCamera, Vec3};

fn v(x: f64, y: f64, z: f64) -> Vec3 {
    Vec3 { x, y, z }
}

fn camera(lens_diameter: f64) -> LensCamera {
    LensCamera::new(
        v(0.0, 0.0, 0.0),
        v(0.0, 0.0, -1.0),
        v(0.0, 1.0, 0.0),
        60.0,
        lens_diameter,
        5.0,
        4,
        2,
    )
    .expect("valid camera")
}

fn close(a: f64, b: f64) -> bool {
    (a - b).abs() <= 1.0e-10
}

fn focus_intersection(ray: &solution::Ray) -> Vec3 {
    let t = (-5.0 - ray.origin.z) / ray.direction.z;
    v(
        ray.origin.x + t * ray.direction.x,
        ray.origin.y + t * ray.direction.y,
        ray.origin.z + t * ray.direction.z,
    )
}

#[test]
fn rejects_each_invalid_construction_category() {
    let make = |eye, aim, up, fov, diameter, focus, width, height| {
        LensCamera::new(eye, aim, up, fov, diameter, focus, width, height)
    };

    assert!(make(v(0.0, 0.0, 0.0), v(0.0, 0.0, -1.0), v(0.0, 1.0, 0.0), 60.0, 0.0, 1.0, 0, 1).is_none());
    assert!(make(v(0.0, 0.0, 0.0), v(0.0, 0.0, -1.0), v(0.0, 1.0, 0.0), 60.0, 0.0, 1.0, 1, 0).is_none());
    for fov in [0.0, 180.0, -1.0, f64::NAN, f64::INFINITY] {
        assert!(make(v(0.0, 0.0, 0.0), v(0.0, 0.0, -1.0), v(0.0, 1.0, 0.0), fov, 0.0, 1.0, 1, 1).is_none());
    }
    assert!(make(v(0.0, 0.0, 0.0), v(0.0, 0.0, -1.0), v(0.0, 1.0, 0.0), 60.0, -0.1, 1.0, 1, 1).is_none());
    assert!(make(v(0.0, 0.0, 0.0), v(0.0, 0.0, -1.0), v(0.0, 1.0, 0.0), 60.0, f64::INFINITY, 1.0, 1, 1).is_none());
    for focus in [0.0, -1.0, f64::NAN, f64::INFINITY] {
        assert!(make(v(0.0, 0.0, 0.0), v(0.0, 0.0, -1.0), v(0.0, 1.0, 0.0), 60.0, 0.0, focus, 1, 1).is_none());
    }
    assert!(make(v(1.0, 2.0, 3.0), v(1.0, 2.0, 3.0), v(0.0, 1.0, 0.0), 60.0, 0.0, 1.0, 1, 1).is_none());
    assert!(make(v(0.0, 0.0, 0.0), v(0.0, 0.0, -1.0), v(0.0, 0.0, 2.0), 60.0, 0.0, 1.0, 1, 1).is_none());
    assert!(make(v(f64::NAN, 0.0, 0.0), v(0.0, 0.0, -1.0), v(0.0, 1.0, 0.0), 60.0, 0.0, 1.0, 1, 1).is_none());
    assert!(make(v(0.0, 0.0, 0.0), v(0.0, f64::INFINITY, -1.0), v(0.0, 1.0, 0.0), 60.0, 0.0, 1.0, 1, 1).is_none());
    assert!(make(v(0.0, 0.0, 0.0), v(0.0, 0.0, -1.0), v(0.0, f64::NAN, 0.0), 60.0, 0.0, 1.0, 1, 1).is_none());
}

#[test]
fn validates_pixels_grid_zero_and_centered_row_major_samples() {
    let cam = camera(1.0);
    assert!(cam.rays_for_pixel(4, 0, 2).is_none());
    assert!(cam.rays_for_pixel(0, 2, 2).is_none());
    assert_eq!(cam.rays_for_pixel(3, 1, 0).unwrap().len(), 0);

    let samples = cam.rays_for_pixel(1, 0, 2).unwrap();
    assert_eq!(samples.len(), 4);
    let expected = [(0.25, 0.25), (0.75, 0.25), (0.25, 0.75), (0.75, 0.75)];
    for ((_, sample), (x, y)) in samples.iter().zip(expected) {
        assert!(close(sample.x, x));
        assert!(close(sample.y, y));
        assert!(sample.x >= 0.0 && sample.x < 1.0);
        assert!(sample.y >= 0.0 && sample.y < 1.0);
    }
}

#[test]
fn rays_are_unit_length_and_lens_uses_diameter_as_diameter() {
    let rays = camera(2.0).rays_for_pixel(2, 1, 4).unwrap();
    for (ray, _) in rays {
        let length = (ray.direction.x * ray.direction.x
            + ray.direction.y * ray.direction.y
            + ray.direction.z * ray.direction.z)
            .sqrt();
        assert!(close(length, 1.0));
        assert!(close(ray.origin.z, 0.0));
        let radial_squared = ray.origin.x * ray.origin.x + ray.origin.y * ray.origin.y;
        assert!(radial_squared <= 1.0 + 1.0e-10, "lens sample exceeded radius diameter/2");
    }
}

#[test]
fn deterministic_lens_rays_converge_with_pinhole_rays_on_focus_plane() {
    let pinhole = camera(0.0).rays_for_pixel(3, 1, 3).unwrap();
    let lens_cam = camera(1.5);
    let first = lens_cam.rays_for_pixel(3, 1, 3).unwrap();
    let second = lens_cam.rays_for_pixel(3, 1, 3).unwrap();
    assert_eq!(first.len(), 9);

    for i in 0..first.len() {
        let (wide, ws) = &first[i];
        let (again, as_) = &second[i];
        let (zero, zs) = &pinhole[i];
        assert!(close(ws.x, zs.x) && close(ws.y, zs.y));
        assert!(close(ws.x, as_.x) && close(ws.y, as_.y));
        assert!(close(wide.origin.x, again.origin.x));
        assert!(close(wide.origin.y, again.origin.y));
        assert!(close(wide.origin.z, again.origin.z));
        assert!(close(wide.direction.x, again.direction.x));
        assert!(close(wide.direction.y, again.direction.y));
        assert!(close(wide.direction.z, again.direction.z));

        let a = focus_intersection(wide);
        let b = focus_intersection(zero);
        assert!(close(a.x, b.x));
        assert!(close(a.y, b.y));
        assert!(close(a.z, b.z));
    }
}

